(function(){var h=document.getElementById('header'),b=document.getElementById('hamburger'),m=document.getElementById('mobileMenu');if(h)addEventListener('scroll',function(){h.classList.toggle('scrolled',scrollY>30)},{passive:true});if(b&&m){var c=function(){b.classList.remove('open');m.classList.remove('open');document.body.style.overflow=''};b.addEventListener('click',function(){b.classList.toggle('open');m.classList.toggle('open');document.body.style.overflow=m.classList.contains('open')?'hidden':''});m.addEventListener('click',function(e){if(e.target.closest('a'))c()})}
var r=document.querySelectorAll('.reveal');if(!('IntersectionObserver'in window)){r.forEach(function(e){e.classList.add('visible')});return}
var o=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');o.unobserve(e.target)}})},{threshold:.08,rootMargin:'0px 0px -50px 0px'});r.forEach(function(e){o.observe(e)});window.closePopup=function(){var p=document.getElementById('popupOverlay');if(!p)return;p.style.opacity='0';p.style.transition='.4s';setTimeout(function(){p.style.display='none';document.body.classList.remove('hidden-scroll')},400)}})();